BEGIN;
-- CLI-created 20261008052025, renamed to reserved next canonical slot.
-- Permanent use locks + truthful, atomic role/method/client-copy snapshots.
-- No approval, legacy hash, AI switch, candidate source or old report is rewritten.
-- Keep exact prior definitions for an empty-install rollback. An adopted
-- snapshot cannot be rolled back: recover the app while preserving the locks.
CREATE TABLE scp_private.interview_content_prior_functions(signature text PRIMARY KEY,definition text NOT NULL);
ALTER TABLE scp_private.interview_content_prior_functions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON scp_private.interview_content_prior_functions FROM PUBLIC,anon,authenticated,service_role;
INSERT INTO scp_private.interview_content_prior_functions
 SELECT signature,pg_get_functiondef(signature::regprocedure) FROM unnest(ARRAY[
 'public.scp_iv_create_case(uuid,text,uuid,text,uuid,text,uuid,uuid)',
 'public.scp_iv_can_write_case(uuid)','public.scp_iv_case_content_manifest(uuid)',
 'public.scp_iv_build_report_basis(uuid)',
 'public.scp_interview_create_version(uuid,text,uuid,text,text,text)']) signature;
INSERT INTO scp_private.interview_content_prior_functions
 SELECT 'constraint:events',pg_get_constraintdef(oid) FROM pg_constraint
 WHERE conrelid='public.scp_interview_case_events'::regclass AND conname='scp_interview_case_events_event_check';
CREATE TABLE scp_private.interview_content_locks (
 kind text NOT NULL CHECK(kind IN('pack','pack_version','method','role','role_version')),
 content_id uuid NOT NULL, locked_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(kind,content_id)
);
CREATE TABLE scp_private.interview_content_snapshots (
 -- Opaque identifier only: case erasure must not remove permanent use locks
 -- or be blocked by non-candidate normative content. Reads still join a live case.
 case_id uuid PRIMARY KEY,
 manifest jsonb NOT NULL CHECK(jsonb_typeof(manifest)='object'),
 frozen_at timestamptz NOT NULL, frozen_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
 provenance text NOT NULL CHECK(provenance IN('case_created','observed_now')),
 CHECK(manifest->>'observation'='frozen_case_content')
);
CREATE TABLE scp_private.interview_content_acknowledgements (
 case_id uuid PRIMARY KEY REFERENCES scp_private.interview_content_snapshots(case_id) ON DELETE RESTRICT,
 manifest_hash text NOT NULL, actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
 acknowledged_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 note text NOT NULL CHECK(length(btrim(note)) BETWEEN 1 AND 4000)
);
CREATE TABLE scp_private.interview_client_copy_versions (
 version_key text PRIMARY KEY, copy jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE scp_private.interview_content_locks ENABLE ROW LEVEL SECURITY;
ALTER TABLE scp_private.interview_content_snapshots ENABLE ROW LEVEL SECURITY;
ALTER TABLE scp_private.interview_content_acknowledgements ENABLE ROW LEVEL SECURITY;
ALTER TABLE scp_private.interview_client_copy_versions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON scp_private.interview_content_locks,scp_private.interview_content_snapshots,
 scp_private.interview_content_acknowledgements,scp_private.interview_client_copy_versions
 FROM PUBLIC,anon,authenticated,service_role;

-- A single small, infrequent governance domain serialises content mutations
-- before rows change. Case binding acquires it before any content SELECT.
-- This covers service_role too; it is not a client-visible lock API.
CREATE FUNCTION scp_private.interview_content_lock() RETURNS void
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT pg_advisory_xact_lock(20370307,1);
$$;
REVOKE ALL ON FUNCTION scp_private.interview_content_lock() FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION scp_private.interview_content_statement_lock() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN PERFORM scp_private.interview_content_lock(); RETURN NULL; END;
$$;
REVOKE ALL ON FUNCTION scp_private.interview_content_statement_lock() FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION scp_private.interview_content_append_only() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 -- The Auth FK may clear an erased actor, exactly as the existing audit ledgers
 -- do. No client/service table grant exists; all other changes are refused.
 IF TG_OP='UPDATE' AND pg_trigger_depth()>1 THEN
  IF TG_TABLE_NAME='interview_content_snapshots' AND to_jsonb(NEW)->>'frozen_by' IS NULL
   AND (to_jsonb(NEW)-'frozen_by')=(to_jsonb(OLD)-'frozen_by') THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME='interview_content_acknowledgements' AND to_jsonb(NEW)->>'actor_id' IS NULL
   AND (to_jsonb(NEW)-'actor_id')=(to_jsonb(OLD)-'actor_id') THEN RETURN NEW; END IF;
 END IF;
 RAISE EXCEPTION 'SCP_IV_CONTENT_RECORD_IMMUTABLE' USING ERRCODE='check_violation';
END;
$$;
REVOKE ALL ON FUNCTION scp_private.interview_content_append_only() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON scp_private.interview_content_locks
 FOR EACH ROW EXECUTE FUNCTION scp_private.interview_content_append_only();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON scp_private.interview_content_snapshots
 FOR EACH ROW EXECUTE FUNCTION scp_private.interview_content_append_only();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON scp_private.interview_content_acknowledgements
 FOR EACH ROW EXECUTE FUNCTION scp_private.interview_content_append_only();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON scp_private.interview_client_copy_versions
 FOR EACH ROW EXECUTE FUNCTION scp_private.interview_content_append_only();

CREATE FUNCTION scp_private.interview_content_owner(_table text,_row jsonb)
RETURNS TABLE(kind text,content_id uuid)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE _id uuid;
BEGIN
 CASE _table
 WHEN 'scp_roles' THEN kind:='role'; _id:=(_row->>'id')::uuid;
 WHEN 'scp_role_versions' THEN kind:='role_version'; _id:=(_row->>'id')::uuid;
 WHEN 'scp_interview_packs' THEN kind:='pack'; _id:=(_row->>'id')::uuid;
 WHEN 'scp_interview_pack_versions' THEN kind:='pack_version'; _id:=(_row->>'id')::uuid;
 WHEN 'scp_interview_methods' THEN kind:='method'; _id:=(_row->>'id')::uuid;
 WHEN 'scp_interview_pack_competencies','scp_interview_core_questions',
      'scp_interview_approved_probes','scp_interview_verification_rules','scp_interview_prohibited_areas'
 THEN kind:='pack_version'; _id:=(_row->>'pack_version_id')::uuid;
 WHEN 'scp_interview_pack_competency_map'
 THEN kind:='pack_version'; SELECT c.pack_version_id INTO _id FROM public.scp_interview_pack_competencies c WHERE c.id=(_row->>'pack_competency_id')::uuid;
 WHEN 'scp_interview_question_competencies','scp_interview_evidence_dimensions'
 THEN kind:='pack_version'; SELECT q.pack_version_id INTO _id FROM public.scp_interview_core_questions q WHERE q.id=(_row->>'question_id')::uuid;
 WHEN 'scp_interview_rating_anchors'
 THEN
  -- The current CHECK allows exactly one parent. Resolve every populated
  -- reference anyway, so no future alternate-parent path can omit a use lock.
  kind:='pack_version';
  IF _row->>'question_id' IS NOT NULL THEN
   SELECT q.pack_version_id INTO _id FROM public.scp_interview_core_questions q WHERE q.id=(_row->>'question_id')::uuid;
   IF _id IS NULL THEN RAISE EXCEPTION 'SCP_IV_CONTENT_PARENT_UNRESOLVED:anchor_question' USING ERRCODE='check_violation'; END IF;
   content_id:=_id; RETURN NEXT;
  END IF;
  IF _row->>'pack_competency_id' IS NOT NULL THEN
   SELECT c.pack_version_id INTO _id FROM public.scp_interview_pack_competencies c WHERE c.id=(_row->>'pack_competency_id')::uuid;
   IF _id IS NULL THEN RAISE EXCEPTION 'SCP_IV_CONTENT_PARENT_UNRESOLVED:anchor_competency' USING ERRCODE='check_violation'; END IF;
   content_id:=_id; RETURN NEXT;
  END IF;
  IF _id IS NULL THEN RAISE EXCEPTION 'SCP_IV_CONTENT_PARENT_UNRESOLVED:anchor' USING ERRCODE='check_violation'; END IF;
  RETURN;
 WHEN 'scp_interview_method_practices','scp_interview_conduct_steps','scp_interview_conduct_guidance',
      'scp_interview_conduct_prohibitions','scp_trust_stages'
 THEN kind:='method'; _id:=(_row->>'method_id')::uuid;
 WHEN 'scp_trust_stage_prohibitions','scp_trust_stage_ai_tasks','scp_trust_stage_claims'
 THEN kind:='method'; SELECT s.method_id INTO _id FROM public.scp_trust_stages s WHERE s.id=(_row->>'stage_id')::uuid;
 ELSE RAISE EXCEPTION 'SCP_IV_CONTENT_UNKNOWN_TABLE:%',_table USING ERRCODE='check_violation';
 END CASE;
 IF _id IS NULL THEN RAISE EXCEPTION 'SCP_IV_CONTENT_PARENT_UNRESOLVED:%',_table USING ERRCODE='check_violation'; END IF;
 content_id:=_id; RETURN NEXT;
END;
$$;
REVOKE ALL ON FUNCTION scp_private.interview_content_owner(text,jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION scp_private.interview_content_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE _old jsonb; _new jsonb; _ref record; _row jsonb;
 _lifecycle text[]:=ARRAY['content_status','validation_label','updated_at','published_by','published_at',
 'suspended_by','suspended_at','suspended_reason','retired_by','retired_at','retired_reason','pilot_availability'];
BEGIN
 IF TG_OP<>'INSERT' THEN _old:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN _new:=to_jsonb(NEW); END IF;
 -- Lifecycle withdrawal remains available. Identity/hash/normative copy do not.
 IF TG_OP='UPDATE' THEN
  IF TG_TABLE_NAME='scp_role_versions' AND (_old-ARRAY['content_status','published_at','retired_at','updated_at'])=(_new-ARRAY['content_status','published_at','retired_at','updated_at']) THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME='scp_interview_pack_versions' AND (_old-_lifecycle)=(_new-_lifecycle) THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME='scp_interview_methods' AND
   (_old-ARRAY['approval_state','approved_at','approved_by','updated_at'])=
   (_new-ARRAY['approval_state','approved_at','approved_by','updated_at']) THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME IN('scp_interview_packs','scp_roles') AND (_old-'updated_at')=(_new-'updated_at') THEN RETURN NEW; END IF;
 END IF;
 FOREACH _row IN ARRAY ARRAY[_old,_new] LOOP
  IF _row IS NULL THEN CONTINUE; END IF;
  FOR _ref IN SELECT * FROM scp_private.interview_content_owner(TG_TABLE_NAME,_row) LOOP
   IF EXISTS(SELECT 1 FROM scp_private.interview_content_locks l WHERE l.kind=_ref.kind AND l.content_id=_ref.content_id) THEN
    RAISE EXCEPTION 'SCP_IV_CONTENT_IN_USE:%:%',_ref.kind,_ref.content_id USING ERRCODE='check_violation';
   END IF;
  END LOOP;
 END LOOP;
 RETURN coalesce(NEW,OLD);
END;
$$;
REVOKE ALL ON FUNCTION scp_private.interview_content_guard() FROM PUBLIC,anon,authenticated,service_role;
DO $$
DECLARE _t text;
BEGIN
 FOREACH _t IN ARRAY ARRAY['scp_roles','scp_role_versions','scp_interview_packs','scp_interview_pack_versions','scp_interview_pack_competencies',
 'scp_interview_core_questions','scp_interview_approved_probes','scp_interview_verification_rules',
 'scp_interview_prohibited_areas','scp_interview_pack_competency_map','scp_interview_question_competencies',
 'scp_interview_evidence_dimensions','scp_interview_rating_anchors','scp_interview_methods',
 'scp_interview_method_practices','scp_interview_conduct_steps','scp_interview_conduct_guidance',
 'scp_interview_conduct_prohibitions','scp_trust_stages','scp_trust_stage_prohibitions',
 'scp_trust_stage_ai_tasks','scp_trust_stage_claims'] LOOP
 EXECUTE format('CREATE TRIGGER ri_content_serialise BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION scp_private.interview_content_statement_lock()',_t);
 EXECUTE format('CREATE TRIGGER ri_content_in_use BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION scp_private.interview_content_guard()',_t);
 END LOOP;
END $$;

