cient evidence.","iiu.ev.needevidence.cta.evidence":"Add evidence for this question","iiu.ev.needevidence.cta.zero":"Choose level 0 – insufficient evidence","iiu.ev.needevidence.locked":"Requires confirmed evidence","iiu.ev.rationale.missing":"Write your reasoning before saving.","iiu.ev.motivering":"Reasoning: ","iiu.ev.ankare":"Behavioural example: ","iiu.err.no_confirmed_evidence":"A level above 0 must rest on confirmed material for this question. With no material, the correct level is 0 – cannot be assessed.","iiu.err.rationale_required":"A level without reasoning is a number, not an assessment. Write why.","iiu.err.no_anchor":"The interview guide defines no behavioural example for that level on this question.","iiu.err.sources_not_ready":"Add material before planning the conversation.","iiu.err.note_stale":"This note was changed somewhere else since it was loaded. Load the saved version.","iiu.err.note_exists":"A saved note already exists for this question. Load the saved version.","iiu.err.note_not_writable":"The note could not be saved: it no longer exists or may not be changed.","iiu.err.evidence_origin":"That material belongs to a different interview and cannot be used here.","iiu.err.proposal_already_reviewed":"This suggestion has already been reviewed. Reload the page to see the outcome.","iiu.err.read_failed":"The interview material could not be loaded. Nothing is lost – try again.","iiu.iv.howto.title":"How to conduct this interview","iiu.iv.howto.1":"Ask the core questions in order, Q1 to Q8. The wording is locked and is read verbatim.","iiu.iv.howto.2":"Use the follow-up questions when you need more detail. Other follow-ups do not belong here.","iiu.iv.howto.3":"Write notes during the conversation. They are saved automatically.","iiu.iv.howto.4":"Mark a question as answered once it is sufficiently covered.","iiu.iv.howto.5":"End the interview when you are finished and continue to the assessment.","iiu.iv.howto.6":"The assessment is made after the interview, against confirmed material — not during the conversation.","iiu.iv.howto.7":"The system makes no employment decision. You do.","iiu.iv.saved.notes":"Your notes are saved","iiu.iv.saving":"Saving …","iiu.iv.marked":"The question is marked as answered","iiu.rp.blk.assessment_not_complete":"The assessment is not finished yet. Go to Assess and choose “Finished assessing” once every question has an assessment.","iiu.rp.blk.question_not_assessed":"has no recorded assessment.","iiu.rp.blk.question_not_assessed.many":"questions have no recorded assessment:","iiu.rp.blk.proposals_awaiting":"AI suggestions are still waiting for human review.","iiu.rp.blk.assessment_predates":"has new confirmed material since it was assessed. Review the assessment again.","iiu.rp.blk.not_permitted":"You do not have access to this interview.","iiu.rp.blk.case_not_found":"This interview does not exist.","iiu.rp.blk.generic":"Something remains before the report can be locked.","iiu.rp.blk.cta":"Back to assessment","iiu.ix.active":"Active interviews","iiu.ix.awaiting":"Waiting for your review","iiu.ix.done":"Finalised reports","iiu.ix.empty":"No interviews yet. Plan one to prepare, conduct and document a competency-based interview.","iiu.ix.stage.inPreparation":"In preparation","iiu.ix.filtered":"Showing only:","iiu.ix.clearFilter":"Show all interviews","iiu.ix.emptyForFilter":"No interviews at this stage right now. The totals above are for the whole organisation.","iiu.ix.startFromCandidate":"An interview is normally started from the candidate, so the application, the job and the material travel with it.","iiu.ix.startFromCandidate.cta":"Go to applications","iiu.ix.caption":"Interviews with status and pending review","iiu.ix.col.interview":"Candidate","iiu.ix.col.pack":"Role","iiu.ix.col.awaiting":"To review","iiu.ix.col.updated":"Last updated","iiu.ix.col.next":"Next step","iiu.ix.proposals":"suggestions","iiu.wf.assess.material":"Choose the material","iiu.wf.assess.judge":"Assess against the requirements","iiu.wf.assess.aria":"Steps within the assessment","iiu.wf.notyet":"not yet","iiu.ov.cta.reviewreport":"Review the report","iiu.lv.method":"Method support","iiu.lv.context.areas":"Areas to follow up","iiu.lv.context.note":"From the application and the assessment. Support for the conversation — none of it has to be asked as a question.","iiu.rp.preview.title":"Report material","iiu.rp.preview.body":"This is what the report will contain: confirmed material and your assessments against the role's requirements. Nothing is generated.","iiu.pp.plan.saveapprove":"Save and approve the plan","iiu.pp.plan.saveapprove.note":"You wrote the plan yourself, so it is approved when it is saved. The interview can then be started.","iiu.pl.conclusion.save":"Save the panel's conclusion","iiu.pl.saving":"Saving …","iiu.pl.you":"You","iiu.pl.srprefix.stage":"Panel stage","iiu.pl.srprefix.member":"Assessor","iiu.pl.srprefix.question":"Question","iiu.ix.boundary.title":"What this product does not do","iiu.ix.boundary.body":"No total score, no ranking, no automatic recommendation and no hiring decision. This is decision support; the decision is made and documented by an authorised person at your organisation.","iiu.new.prefill.unavailable":"The details from the application could not be loaded, so the fields below are empty. The interview is still linked to the application when it is created."}}$copy$::jsonb);

CREATE FUNCTION scp_private.interview_capture_content(_case_id uuid,_provenance text) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE _c public.scp_interview_cases%ROWTYPE; _manifest jsonb; _content jsonb;
 _copy jsonb; _copy_version text; _at timestamptz:=clock_timestamp(); _pack_id uuid; _role_id uuid;
BEGIN
 PERFORM scp_private.interview_content_lock();
 SELECT * INTO _c FROM public.scp_interview_cases WHERE id=_case_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'SCP_IV_CASE_NOT_FOUND' USING ERRCODE='check_violation'; END IF;
 IF EXISTS(SELECT 1 FROM scp_private.interview_content_snapshots WHERE case_id=_case_id) THEN RETURN; END IF;
 SELECT pack_id INTO _pack_id FROM public.scp_interview_pack_versions WHERE id=_c.pack_version_id;
 INSERT INTO scp_private.interview_content_locks(kind,content_id)
 VALUES('pack',_pack_id),('pack_version',_c.pack_version_id) ON CONFLICT DO NOTHING;
 SELECT role_id INTO _role_id FROM public.scp_role_versions WHERE id=_c.role_version_id;
 INSERT INTO scp_private.interview_content_locks(kind,content_id) VALUES('role',_role_id),('role_version',_c.role_version_id) ON CONFLICT DO NOTHING;
 IF _c.trust_method_id IS NOT NULL THEN
 INSERT INTO scp_private.interview_content_locks(kind,content_id) VALUES('method',_c.trust_method_id) ON CONFLICT DO NOTHING;
 END IF;
 SELECT version_key,copy INTO _copy_version,_copy FROM scp_private.interview_client_copy_versions ORDER BY created_at DESC,version_key DESC LIMIT 1;
 _manifest:=scp_private.interview_content_manifest(_case_id);
 _content:=(_manifest->'content')||jsonb_build_object('client_copy',_copy,'client_copy_version',_copy_version,
 'role',(SELECT to_jsonb(r) FROM public.scp_roles r WHERE r.id=_role_id),
 'role_version',(SELECT to_jsonb(v) FROM public.scp_role_versions v WHERE v.id=_c.role_version_id),
 'trust_stages',coalesce((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.ordinal,s.id) FROM public.scp_trust_stages s WHERE s.method_id=_c.trust_method_id),'[]'::jsonb),
 'trust_claims',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id) FROM public.scp_trust_stage_claims a JOIN public.scp_trust_stages s ON s.id=a.stage_id WHERE s.method_id=_c.trust_method_id),'[]'::jsonb),
 'trust_ai_tasks',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id)
  FROM public.scp_trust_stage_ai_tasks a JOIN public.scp_trust_stages s ON s.id=a.stage_id WHERE s.method_id=_c.trust_method_id),'[]'::jsonb));
 _manifest:=_manifest||jsonb_build_object('observation','frozen_case_content','content',_content,
 'manifest_hash',encode(sha256(convert_to(_content::text,'UTF8')),'hex'),
 'freeze_provenance',_provenance,'frozen_at',_at,'client_copy_version',_copy_version);
 INSERT INTO scp_private.interview_content_snapshots(case_id,manifest,frozen_at,frozen_by,provenance)
 VALUES(_case_id,_manifest,_at,auth.uid(),_provenance);
END;
$$;
REVOKE ALL ON FUNCTION scp_private.interview_capture_content(uuid,text) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION scp_private.interview_case_content_bind() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE _v public.scp_interview_pack_versions%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.pack_version_id IS DISTINCT FROM OLD.pack_version_id
   OR NEW.role_version_id IS DISTINCT FROM OLD.role_version_id
   OR NEW.pack_content_hash IS DISTINCT FROM OLD.pack_content_hash
   OR NEW.trust_method_id IS DISTINCT FROM OLD.trust_method_id THEN
   RAISE EXCEPTION 'SCP_IV_CONTENT_BIND_IMMUTABLE: create an explicitly linked new case and new plan instead' USING ERRCODE='check_violation';
  END IF;
  RETURN NEW;
 END IF;
 IF public.scp_iv_case_start_basis(NEW.employer_id,NEW.pack_version_id,auth.uid()) IS NULL THEN
  RAISE EXCEPTION 'SCP_IV_PACK_NOT_USABLE' USING ERRCODE='insufficient_privilege';
 END IF;
 SELECT * INTO _v FROM public.scp_interview_pack_versions WHERE id=NEW.pack_version_id;
 NEW.role_version_id:=_v.role_version_id; NEW.pack_content_hash:=_v.content_hash;
 IF NEW.trust_method_id IS NULL THEN
 NEW.trust_method_id:=public.scp_trust_eligible_method(CASE WHEN _v.content_status='published' THEN 'production' ELSE 'internal_qa' END);
 END IF;
 RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION scp_private.interview_case_content_bind() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER ri_content_serialise BEFORE INSERT ON public.scp_interview_cases
 FOR EACH STATEMENT EXECUTE FUNCTION scp_private.interview_content_statement_lock();
CREATE TRIGGER ri_content_bind BEFORE INSERT OR UPDATE ON public.scp_interview_cases
 FOR EACH ROW EXECUTE FUNCTION scp_private.interview_case_content_bind();
CREATE FUNCTION scp_private.interview_case_content_capture() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN PERFORM scp_private.interview_capture_content(NEW.id,'case_created'); RETURN NEW; END;
$$;
REVOKE ALL ON FUNCTION scp_private.interview_case_content_capture() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER ri_content_capture AFTER INSERT ON public.scp_interview_cases
 FOR EACH ROW EXECUTE FUNCTION scp_private.interview_case_content_capture();

-- Lock before the create RPC's first SELECT, so eligibility and copy share
-- the same serialisation point as direct INSERT and all content mutations.
DO $$
DECLARE _def text;
BEGIN
 SELECT pg_get_functiondef('public.scp_iv_create_case(uuid,text,uuid,text,uuid,text,uuid,uuid)'::regprocedure) INTO _def;
 IF position('SCP_IV_CANDIDATE_NOT_APPLICANT' in _def)=0 THEN RAISE EXCEPTION 'SCP_IV_SNAPSHOT_CREATE_PRECONDITION'; END IF;
 _def:=regexp_replace(_def,E'BEGIN\n',E'BEGIN\n  PERFORM scp_private.interview_content_lock();\n');
 EXECUTE _def;
END $$;

-- Truthful migration inventory: freeze what exists NOW, never "at creation".
-- No old reports or old stored pack hashes are changed.
DO $$ DECLARE _id uuid;
BEGIN
 PERFORM scp_private.interview_content_lock();
 FOR _id IN SELECT id FROM public.scp_interview_cases ORDER BY id LOOP
  PERFORM scp_private.interview_capture_content(_id,'observed_now');
 END LOOP;
END $$;

CREATE FUNCTION scp_private.interview_frozen_manifest(_case_id uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE _manifest jsonb;
BEGIN
 SELECT manifest INTO _manifest FROM scp_private.interview_content_snapshots WHERE case_id=_case_id;
 IF _manifest IS NULL THEN RAISE EXCEPTION 'SCP_IV_CONTENT_SNAPSHOT_MISSING' USING ERRCODE='check_violation'; END IF;
 RETURN _manifest;
END;
$$;
REVOKE ALL ON FUNCTION scp_private.interview_frozen_manifest(uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION scp_private.interview_content_ready(_case_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM scp_private.interview_content_snapshots s WHERE s.case_id=_case_id AND
 (s.provenance='case_created' OR EXISTS(SELECT 1 FROM scp_private.interview_content_acknowledgements a
 WHERE a.case_id=s.case_id AND a.manifest_hash=s.manifest->>'manifest_hash')));
$$;
REVOKE ALL ON FUNCTION scp_private.interview_content_ready(uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.scp_iv_case_frozen_content(_case_id uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NOT public.scp_iv_can_read_case(_case_id) THEN RAISE EXCEPTION 'INTERVIEW_CASE_NOT_FOUND' USING ERRCODE='insufficient_privilege'; END IF;
 RETURN (SELECT jsonb_build_object('manifest',s.manifest,'frozen_at',s.frozen_at,'provenance',s.provenance,
 'requires_acknowledgement',NOT scp_private.interview_content_ready(_case_id),
 'may_acknowledge',public.has_active_employer_role(auth.uid(),c.employer_id,ARRAY['owner','admin']),
 'acknowledged_at',(SELECT acknowledged_at FROM scp_private.interview_content_acknowledgements WHERE case_id=s.case_id))
 FROM scp_private.interview_content_snapshots s JOIN public.scp_interview_cases c ON c.id=s.case_id WHERE s.case_id=_case_id);
END;
$$;
REVOKE ALL ON FUNCTION public.scp_iv_case_frozen_content(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.scp_iv_case_frozen_content(uuid) TO authenticated;

DO $$ DECLARE _check text;
BEGIN
 SELECT pg_get_constraintdef(oid) INTO _check FROM pg_constraint
 WHERE conrelid='public.scp_interview_case_events'::regclass AND conname='scp_interview_case_events_event_check';
 IF _check IS NULL THEN RAISE EXCEPTION 'SCP_IV_CONTENT_EVENT_PRECONDITION'; END IF;
 ALTER TABLE public.scp_interview_case_events DROP CONSTRAINT scp_interview_case_events_event_check;
 EXECUTE 'ALTER TABLE public.scp_interview_case_events ADD CONSTRAINT scp_interview_case_events_event_check CHECK ('
 || substring(_check FROM 8 FOR length(_check)-8) || ' OR event = ''content_snapshot_acknowledged'')';
END $$;

CREATE FUNCTION public.scp_iv_acknowledge_observed_content(_case_id uuid,_expected_manifest_hash text,_note text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE _c public.scp_interview_cases%ROWTYPE; _s scp_private.interview_content_snapshots%ROWTYPE;
BEGIN
 SELECT * INTO _c FROM public.scp_interview_cases WHERE id=_case_id FOR UPDATE;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT public.has_active_employer_role(auth.uid(),_c.employer_id,ARRAY['owner','admin'])
  OR NOT public.scp_iv_can_read_case(_case_id) THEN RAISE EXCEPTION 'INTERVIEW_CASE_NOT_FOUND' USING ERRCODE='insufficient_privilege'; END IF;
 SELECT * INTO _s FROM scp_private.interview_content_snapshots WHERE case_id=_case_id;
 IF _s.provenance<>'observed_now' THEN RAISE EXCEPTION 'SCP_IV_CONTENT_NOT_LEGACY' USING ERRCODE='check_violation'; END IF;
 IF _expected_manifest_hash IS DISTINCT FROM _s.manifest->>'manifest_hash' THEN RAISE EXCEPTION 'SCP_IV_CONTENT_STALE' USING ERRCODE='serialization_failure'; END IF;
 IF _note IS NULL OR length(btrim(_note)) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'SCP_IV_CONTENT_NOTE_REQUIRED' USING ERRCODE='check_violation'; END IF;
 IF EXISTS(SELECT 1 FROM scp_private.interview_content_acknowledgements WHERE case_id=_case_id) THEN RETURN public.scp_iv_case_frozen_content(_case_id); END IF;
 INSERT INTO scp_private.interview_content_acknowledgements(case_id,manifest_hash,actor_id,note)
 VALUES(_case_id,_expected_manifest_hash,auth.uid(),btrim(_note));
 PERFORM public.scp_iv_record_event(_case_id,'content_snapshot_acknowledged','human',NULL,NULL,NULL,btrim(_note),
 jsonb_build_object('content_snapshot_acknowledged',true,'provenance','observed_now','manifest_hash',_expected_manifest_hash));
 RETURN public.scp_iv_case_frozen_content(_case_id);
END;
$$;
REVOKE ALL ON FUNCTION public.scp_iv_acknowledge_observed_content(uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.scp_iv_acknowledge_observed_content(uuid,text,text) TO authenticated;

CREATE FUNCTION public.scp_iv_content_inventory(_employer_id uuid)
RETURNS TABLE(case_id uuid,status text,created_at timestamptz,provenance text,frozen_at timestamptz,manifest_hash text,requires_acknowledgement boolean)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT public.has_active_employer_role(auth.uid(),_employer_id,ARRAY['owner','admin'])
 THEN RAISE EXCEPTION 'SCP_IV_CONTENT_INVENTORY_ROLE' USING ERRCODE='insufficient_privilege'; END IF;
 RETURN QUERY SELECT c.id,c.status,c.created_at,s.provenance,s.frozen_at,s.manifest->>'manifest_hash',NOT scp_private.interview_content_ready(c.id)
 FROM public.scp_interview_cases c JOIN scp_private.interview_content_snapshots s ON s.case_id=c.id
 WHERE c.employer_id=_employer_id ORDER BY c.created_at,c.id;
END;
$$;
REVOKE ALL ON FUNCTION public.scp_iv_content_inventory(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.scp_iv_content_inventory(uuid) TO authenticated;

-- Keep authorization in its original body; add the explicit legacy content gate.
DO $$ DECLARE _def text;
BEGIN
 SELECT pg_get_functiondef('public.scp_iv_can_write_case(uuid)'::regprocedure) INTO _def;
 IF position('AND public.bcp_case_access_ok(_case_id)' IN _def)=0 THEN RAISE EXCEPTION 'SCP_IV_CONTENT_WRITE_PRECONDITION'; END IF;
 _def:=replace(_def,'AND public.bcp_case_access_ok(_case_id)','AND public.bcp_case_access_ok(_case_id) AND scp_private.interview_content_ready(_case_id)');
 EXECUTE _def;
END $$;

-- Fail closed across direct table/service writes, including owner/admin report
-- and finding review paths that intentionally have stronger roles than can_write.
-- Erasure, source withdrawal and candidate factual correction remain available.
CREATE FUNCTION scp_private.interview_content_review_gate() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE _row jsonb; _case uuid;
BEGIN
 IF TG_TABLE_NAME='scp_interview_cases' THEN
  IF NEW.status IS NOT DISTINCT FROM OLD.status OR NEW.status='cancelled' THEN RETURN NEW; END IF;
  _case:=NEW.id;
 ELSE
  _row:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  _case:=(_row->>'case_id')::uuid;
  IF _case IS NULL AND _row ? 'session_id' THEN _case:=public.scp_iv_session_case((_row->>'session_id')::uuid); END IF;
  IF _case IS NULL AND _row ? 'plan_id' THEN _case:=public.scp_iv_plan_case((_row->>'plan_id')::uuid); END IF;
  IF _case IS NULL AND _row ? 'panel_id' THEN SELECT case_id INTO _case FROM public.scp_interview_panels WHERE id=(_row->>'panel_id')::uuid; END IF;
 END IF;
 IF _case IS NULL OR NOT scp_private.interview_content_ready(_case) THEN
  RAISE EXCEPTION 'SCP_IV_CONTENT_REVIEW_REQUIRED' USING ERRCODE='check_violation';
 END IF;
 RETURN coalesce(NEW,OLD);
END;
$$;
REVOKE ALL ON FUNCTION scp_private.interview_content_review_gate() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER ri_content_review BEFORE UPDATE ON public.scp_interview_cases
 FOR EACH ROW EXECUTE FUNCTION scp_private.interview_content_review_gate();
DO $$ DECLARE _t text;
BEGIN
 FOREACH _t IN ARRAY ARRAY['scp_interview_prep_plans','scp_interview_prep_items','scp_interview_sessions',
 'scp_interview_session_questions','scp_interview_session_notes','scp_interview_probe_usages',
 'scp_interview_findings','scp_interview_role_requirements','scp_interview_candidate_facts',
 'scp_interview_evidence_proposals','scp_interview_evidence','scp_interview_assessments',
 'scp_interview_panels','scp_interview_panel_members','scp_interview_reports'] LOOP
 EXECUTE format('CREATE TRIGGER ri_content_review BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION scp_private.interview_content_review_gate()',_t);
 END LOOP;
END $$;

-- The backward-compatible manifest endpoint now returns frozen content honestly.
CREATE OR REPLACE FUNCTION public.scp_iv_case_content_manifest(_case_id uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NOT public.scp_iv_can_read_case(_case_id) THEN RAISE EXCEPTION 'INTERVIEW_CASE_NOT_FOUND' USING ERRCODE='insufficient_privilege'; END IF;
 RETURN scp_private.interview_frozen_manifest(_case_id);
END;
$$;
REVOKE ALL ON FUNCTION public.scp_iv_case_content_manifest(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.scp_iv_case_content_manifest(uuid) TO authenticated;

-- Report guide texts really come from the saved JSON, not just equal live rows.
DO $$ DECLARE _def text; _table text; _key text; _replacement text;
BEGIN
 SELECT pg_get_functiondef('public.scp_iv_build_report_basis(uuid)'::regprocedure) INTO _def;
 IF position('interview_foundation_version' IN _def)=0 THEN RAISE EXCEPTION 'SCP_IV_CONTENT_REPORT_PRECONDITION'; END IF;
 _def:=replace(_def,E'DECLARE\n',E'DECLARE\n  _frozen jsonb;\n');
 _def:=replace(_def,'  -- Built ONLY',E'  _frozen := scp_private.interview_frozen_manifest(_case_id);\n  -- Built ONLY');
 _def:=replace(_def,'scp_private.interview_content_manifest(_case_id)','scp_private.interview_frozen_manifest(_case_id)');
 FOREACH _table IN ARRAY ARRAY['scp_interview_packs','scp_interview_pack_versions','scp_interview_core_questions',
 'scp_interview_pack_competencies','scp_interview_question_competencies','scp_interview_rating_anchors'] LOOP
 _key:=CASE _table WHEN 'scp_interview_packs' THEN 'pack' WHEN 'scp_interview_pack_versions' THEN 'pack_version'
 WHEN 'scp_interview_core_questions' THEN 'questions' WHEN 'scp_interview_pack_competencies' THEN 'competencies'
 WHEN 'scp_interview_question_competencies' THEN 'question_competencies' ELSE 'anchors' END;
 IF _table='scp_interview_packs' THEN
 _replacement:=format('(SELECT * FROM jsonb_populate_record(NULL::public.%I,_frozen->''content''->''pack''))',_table);
 ELSIF _table='scp_interview_pack_versions' THEN
 _replacement:=format('(SELECT * FROM jsonb_populate_record(NULL::public.%I,(_frozen->''content''->''pack_version'')||jsonb_build_object(''validation_label'',_frozen->>''pack_validation_label'')))',_table);
 ELSE _replacement:=format('(SELECT * FROM jsonb_populate_recordset(NULL::public.%I,_frozen->''content''->%L))',_table,_key); END IF;
 -- Replace FROM/JOIN occurrences only; retain composite types above.
 _def:=replace(_def,'FROM public.'||_table||' ','FROM '||_replacement||' ');
 _def:=replace(_def,'JOIN public.'||_table||' ','JOIN '||_replacement||' ');
 END LOOP;
 EXECUTE _def;
END $$;

-- A frozen used draft is not an editable open draft. A new version can be
-- authored without deleting/approving the old used version.
DO $$ DECLARE _def text;
BEGIN
 SELECT pg_get_functiondef('public.scp_interview_create_version(uuid,text,uuid,text,text,text)'::regprocedure) INTO _def;
 IF position('SCP_INTERVIEW_OPEN_VERSION_EXISTS' IN _def)=0 THEN RAISE EXCEPTION 'SCP_IV_CONTENT_NEW_VERSION_PRECONDITION'; END IF;
 _def:=regexp_replace(_def,E'BEGIN\n',E'BEGIN\n  PERFORM scp_private.interview_content_lock();\n');
 _def:=replace(_def,'AND v.content_status IN (''draft'', ''expert_review'', ''legal_review'', ''cognitive_review''))',
 'AND v.content_status IN (''draft'', ''expert_review'', ''legal_review'', ''cognitive_review'')
 AND NOT EXISTS(SELECT 1 FROM scp_private.interview_content_locks l WHERE l.kind=''pack_version'' AND l.content_id=v.id))');
 EXECUTE _def;
END $$;

COMMIT;
